#pragma once

#include "CoreMinimal.h"
#include "GameFramework/GameModeBase.h"
#include "ArenaGameMode.generated.h"

class UArenaHud;
class UArenaPalette;
class UArenaScoreTracker;
struct FArenaStats;

UCLASS()
class PIXELARENA_API AArenaGameMode : public AGameModeBase
{
	GENERATED_BODY()

public:
	virtual void BeginPlay() override;
	virtual void EndPlay(const EEndPlayReason::Type Reason) override;

	void OnGoalScored(int32 TeamIndex);

private:
	UPROPERTY()
	TObjectPtr<UArenaHud> Hud;

	UPROPERTY()
	TObjectPtr<UArenaPalette> Palette;

	UPROPERTY()
	TObjectPtr<UArenaScoreTracker> ScoreTracker;

	// Plain C++ data owned by this class, freed in EndPlay.
	FArenaStats* Stats = nullptr;
};


--- result.json ---
{
  "crash_cause": "UArenaScoreTracker (a UObject) was created with NewObject but stored in a raw, non-UPROPERTY pointer (UArenaScoreTracker* ScoreTracker) in AArenaGameMode. Unmanaged UObjects with no other references are purged by garbage collection (log: 'Collecting garbage: 412 objects purged'), leaving a dangling pointer; the first goal ~1.5 min into the run called AddPoints on the freed object, crashing with EXCEPTION_ACCESS_VIOLATION in UArenaScoreTracker::AddPoints() via AArenaGameMode::OnGoalScored(). Fixed by making the member UPROPERTY() TObjectPtr<UArenaScoreTracker> so the GC keeps it alive.",
  "no_colors_cause": "The palette asset /Game/Data/Palettes/DA_Primary was not cooked into the packaged build, so LoadObject returned null and the game fell back to gray (log: \"Couldn't find file for package /Game/Data/Palettes/DA_Primary\", \"Palette is null, using fallback gray\"). It was missing because Config/DefaultGame.ini listed only /Game/Maps/Arena in MapsToCook and /Game/Data/Effects in DirectoriesToAlwaysCook, never the Palettes directory (it is not referenced by the map or any cooked asset). Fixed by adding +DirectoriesToAlwaysCook=(Path=\"/Game/Data/Palettes\") so the palette is cooked into the pak."
}
